      // { id: 33, statement: "Hands in pockets.", answer: false, explanation: "It makes you look closed off. Keep them out and relaxed." },
      // { id: 34, statement: "Nervous = Human.", answer: true, explanation: "Everyone gets nervous. Admitting it can actually be a great icebreaker." },
      // { id: 35, statement: "One word answers.", answer: false, explanation: "Try to add a little more. Instead of 'Yes,' try 'Yes, because...'" },
      // { id: 36, statement: "Ask for help.", answer: true, explanation: "Asking 'Where is the best tea here?' is an easy, safe way to start a talk." },
