      // { id: 38, statement: "Polite to all.", answer: true, explanation: "Being nice to waiters and staff shows your true, high-quality character." },
      // { id: 40, statement: "Space = Comfort.", answer: true, explanation: "Respecting her personal space makes her feel safe around you." },
